export const specSources: Record<string, { yaml: string; data: unknown }> = {
  "checkout-conversion": { yaml: "id: checkout-conversion\nname: Checkout conversion\naliases:\n  - Checkout completion rate\n  - Checkout conversion rate\n  - Checkout success rate\nfamily: conversion\ncatalog_id: checkout_completion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of started checkouts that become a paid order in the same week.\n  formula: Paid orders ÷ checkouts started\n\nevents:\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: checkouts started a week\n  typical: 0.62\n\nexample:\n  business: store\n  level: 0.63\n  volume: 9400\n  trend: 0.02\n\ndrivers:\n  - id: payment-failures\n    label: Payment failures\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did payment success fall, and is it one gateway, card brand or wallet?\n      yes: Declines or errors rise for one processor or method while the others hold.\n    spiked:\n      check: Did a payment problem from the week before just clear?\n      yes: Payment success returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls several points while desktop is flat, which points at a release or layout bug.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n  - id: shipping-and-fees\n    label: Shipping cost and delivery dates\n    dropped:\n      check: Did shipping prices, thresholds or delivery promises change this week?\n      yes: Drop-off concentrates on the shipping step, starting the day the change shipped.\n    spiked:\n      check: Did a free-shipping threshold or faster delivery promise go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n  - id: discount-codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    dropped:\n      check: Did a popular code expire, or did a coupon site start listing codes that fail?\n      yes: More sessions enter a code field and leave after an invalid-code message.\n    spiked:\n      check: Is a sale or a leaked code pushing people through?\n      yes: Code usage jumps and order value per order falls.\n  - id: traffic-mix\n    label: Who reached checkout\n    metric: checkout-start-rate\n    breakdown: $utm_source\n    dropped:\n      check: Did more low-intent visitors reach checkout, for example from a new campaign?\n      yes: Checkout starts rise from one source whose completion is far below the rest.\n    spiked:\n      check: Did fewer but more committed visitors reach checkout?\n      yes: Checkout starts fall while completion rises; orders barely move.\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did an event, consent banner or tag manager change stop orders being recorded?\n      yes: Orders in the payment processor hold steady while recorded orders fall.\n    spiked:\n      check: Is a duplicate order event or a missing checkout event inflating the rate?\n      yes: Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform.\n\ndiagnose_order: [tracking, payment-failures, device-split, shipping-and-fees, discount-codes, traffic-mix]\n\nrelated: [checkout-start-rate, payment-success-rate, conversion-rate, cart-abandonment-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout is the last step a store controls, so a change here is rarely about demand and\n    almost always about something the team shipped, a partner that broke, or a price the\n    shopper saw late. A one-point drop on a store that starts 10,000 checkouts a week is\n    about 100 lost orders, every week, until someone finds it.\n  pitfalls:\n    - Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.\n    - Mixing checkout attempts and sessions in one ratio. Pick one unit for both sides; this spec uses sessions.\n    - Reading a week-over-week move without the volume. Below about 1,000 checkouts a week, a two-point swing is often chance.\n    - Comparing Black Friday week with the week before. Intent is different; compare with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-conversion","name":"Checkout conversion","aliases":["Checkout completion rate","Checkout conversion rate","Checkout success rate"],"family":"conversion","catalog_id":"checkout_completion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of started checkouts that become a paid order in the same week.","formula":"Paid orders ÷ checkouts started"},"events":[{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"checkouts started a week","typical":0.62},"example":{"business":"store","level":0.63,"volume":9400,"trend":0.02},"drivers":[{"id":"payment-failures","label":"Payment failures","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did payment success fall, and is it one gateway, card brand or wallet?","yes":"Declines or errors rise for one processor or method while the others hold."},"spiked":{"check":"Did a payment problem from the week before just clear?","yes":"Payment success returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls several points while desktop is flat, which points at a release or layout bug."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}},{"id":"shipping-and-fees","label":"Shipping cost and delivery dates","dropped":{"check":"Did shipping prices, thresholds or delivery promises change this week?","yes":"Drop-off concentrates on the shipping step, starting the day the change shipped."},"spiked":{"check":"Did a free-shipping threshold or faster delivery promise go live?","yes":"Fewer exits at the shipping step from the day it launched."}},{"id":"discount-codes","label":"Discount codes","metric":"promo-code-usage-rate","dropped":{"check":"Did a popular code expire, or did a coupon site start listing codes that fail?","yes":"More sessions enter a code field and leave after an invalid-code message."},"spiked":{"check":"Is a sale or a leaked code pushing people through?","yes":"Code usage jumps and order value per order falls."}},{"id":"traffic-mix","label":"Who reached checkout","metric":"checkout-start-rate","breakdown":"$utm_source","dropped":{"check":"Did more low-intent visitors reach checkout, for example from a new campaign?","yes":"Checkout starts rise from one source whose completion is far below the rest."},"spiked":{"check":"Did fewer but more committed visitors reach checkout?","yes":"Checkout starts fall while completion rises; orders barely move."}},{"id":"tracking","label":"Tracking change","dropped":{"check":"Did an event, consent banner or tag manager change stop orders being recorded?","yes":"Orders in the payment processor hold steady while recorded orders fall."},"spiked":{"check":"Is a duplicate order event or a missing checkout event inflating the rate?","yes":"Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform."}}],"diagnose_order":["tracking","payment-failures","device-split","shipping-and-fees","discount-codes","traffic-mix"],"related":["checkout-start-rate","payment-success-rate","conversion-rate","cart-abandonment-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Checkout is the last step a store controls, so a change here is rarely about demand and almost always about something the team shipped, a partner that broke, or a price the shopper saw late. A one-point drop on a store that starts 10,000 checkouts a week is about 100 lost orders, every week, until someone finds it.","pitfalls":["Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.","Mixing checkout attempts and sessions in one ratio. Pick one unit for both sides; this spec uses sessions.","Reading a week-over-week move without the volume. Below about 1,000 checkouts a week, a two-point swing is often chance.","Comparing Black Friday week with the week before. Intent is different; compare with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mrr": { yaml: "id: mrr\nname: Monthly recurring revenue\naliases:\n  - MRR\n  - Monthly recurring revenue (MRR)\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.\n  formula: Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR at week end\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- MRR at the end of each of the last 26 weeks: each subscription's latest state before the week closed.\n    SELECT toString(week) AS week, sum(mrr) AS value\n    FROM (\n      SELECT\n        w.week AS week,\n        e.subscription_id AS subscription_id,\n        argMax(e.mrr, e.ts) AS mrr,\n        argMax(e.status, e.ts) AS status\n      FROM (\n        SELECT arrayJoin(arrayMap(i -> toMonday(now()) - toIntervalWeek(i), range(1, 27))) AS week\n      ) AS w\n      CROSS JOIN (\n        SELECT\n          toString(properties.subscription_id) AS subscription_id,\n          toFloat(properties.mrr) AS mrr,\n          toString(properties.status) AS status,\n          timestamp AS ts\n        FROM events\n        WHERE event = 'subscription_updated'\n      ) AS e\n      WHERE e.ts < w.week + toIntervalWeek(1)\n      GROUP BY week, subscription_id\n    )\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- MRR at the end of each week from a subscription change log.\n    WITH weeks AS (\n      SELECT generate_series(\n        date_trunc('week', now() - interval '26 weeks'),\n        date_trunc('week', now()) - interval '1 week',\n        interval '1 week'\n      ) AS week\n    ),\n    latest AS (\n      SELECT DISTINCT ON (w.week, e.properties->>'subscription_id')\n        w.week,\n        (e.properties->>'mrr')::numeric AS mrr,\n        e.properties->>'status' AS status\n      FROM weeks w\n      JOIN events e\n        ON e.event_name = 'subscription_updated'\n       AND e.occurred_at < w.week + interval '1 week'\n      ORDER BY w.week, e.properties->>'subscription_id', e.occurred_at DESC\n    )\n    SELECT week::date AS week, sum(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- MRR at the end of each week from a subscription change log.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(\n        DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 26 WEEK), ISOWEEK),\n        DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK),\n        INTERVAL 1 WEEK\n      )) AS week\n    ),\n    latest AS (\n      SELECT\n        w.week,\n        JSON_VALUE(e.properties, '$.subscription_id') AS subscription_id,\n        CAST(JSON_VALUE(e.properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(e.properties, '$.status') AS status\n      FROM weeks AS w\n      JOIN events AS e\n        ON e.event_name = 'subscription_updated'\n       AND DATE(e.occurred_at) < DATE_ADD(w.week, INTERVAL 1 WEEK)\n      QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY w.week, JSON_VALUE(e.properties, '$.subscription_id')\n        ORDER BY e.occurred_at DESC\n      ) = 1\n    )\n    SELECT week, SUM(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- MRR at the end of each week from a subscription change log. Assumes WEEK_START = 1 (Monday).\n    WITH weeks AS (\n      SELECT DATEADD(week, -SEQ4(), DATE_TRUNC('week', DATEADD(week, -1, CURRENT_DATE()))) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    latest AS (\n      SELECT\n        w.week,\n        e.properties:subscription_id::string AS subscription_id,\n        e.properties:mrr::float AS mrr,\n        e.properties:status::string AS status\n      FROM weeks AS w\n      JOIN events AS e\n        ON e.event_name = 'subscription_updated'\n       AND e.occurred_at < DATEADD(week, 1, w.week)\n      QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY w.week, e.properties:subscription_id::string\n        ORDER BY e.occurred_at DESC\n      ) = 1\n    )\n    SELECT week, SUM(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: active subscriptions\n  typical: 180000\n\nexample:\n  business: saas\n  level: 240000\n  volume: 1900\n  trend: 0.35\n\ndrivers:\n  - id: new-mrr\n    label: New MRR\n    metric: new-mrr\n    dropped:\n      check: Did fewer new customers start paying, or start on smaller plans?\n      yes: New MRR falls below its usual range while churn holds.\n    spiked:\n      check: Did a launch, a sales push or one large deal add new MRR?\n      yes: New MRR jumps; check whether one customer accounts for most of it.\n  - id: expansion\n    label: Expansion\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow?\n      yes: Expansion MRR falls while new and churned MRR hold.\n    spiked:\n      check: Did a price change or a usage limit push customers to upgrade?\n      yes: Expansion MRR jumps in the week the change shipped.\n  - id: churn\n    label: Churned and contracted MRR\n    metric: churned-mrr\n    feed: stripe\n    dropped:\n      check: Did cancellations, downgrades or failed renewals rise?\n      yes: Churned MRR rises; failed payments or one large account explain most of it.\n    spiked:\n      check: Did churn fall unusually low, or did failed payments recover?\n      yes: Churned MRR falls and recovered dunning payments appear.\n  - id: billing-calendar\n    label: Billing calendar\n    dropped:\n      check: Did a cohort of annual plans come up for renewal this week?\n      yes: A cluster of renewals dated one year after a big signup month.\n    spiked:\n      check: Is a migration or a currency revaluation changing amounts without customers acting?\n      yes: Many subscriptions change amount on the same day with no plan change.\n\ndiagnose_order: [billing-calendar, churn, new-mrr, expansion]\n\nrelated: [new-mrr, expansion-mrr, churned-mrr, net-new-mrr, arpa]\n\nprose:\n  why_it_matters: >-\n    MRR is the stock that every other subscription number flows into: new and expansion MRR\n    add to it, churn and contraction take from it. Because it is a stock, it barely moves week\n    to week, which is exactly why a small move matters. Read its flows to see why it moved;\n    read MRR itself to see whether the business is growing.\n  pitfalls:\n    - Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.\n    - Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.\n    - Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.\n    - A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mrr","name":"Monthly recurring revenue","aliases":["MRR","Monthly recurring revenue (MRR)"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.","formula":"Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR at week end","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- MRR at the end of each of the last 26 weeks: each subscription's latest state before the week closed.\nSELECT toString(week) AS week, sum(mrr) AS value\nFROM (\n  SELECT\n    w.week AS week,\n    e.subscription_id AS subscription_id,\n    argMax(e.mrr, e.ts) AS mrr,\n    argMax(e.status, e.ts) AS status\n  FROM (\n    SELECT arrayJoin(arrayMap(i -> toMonday(now()) - toIntervalWeek(i), range(1, 27))) AS week\n  ) AS w\n  CROSS JOIN (\n    SELECT\n      toString(properties.subscription_id) AS subscription_id,\n      toFloat(properties.mrr) AS mrr,\n      toString(properties.status) AS status,\n      timestamp AS ts\n    FROM events\n    WHERE event = 'subscription_updated'\n  ) AS e\n  WHERE e.ts < w.week + toIntervalWeek(1)\n  GROUP BY week, subscription_id\n)\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week","postgres":"-- MRR at the end of each week from a subscription change log.\nWITH weeks AS (\n  SELECT generate_series(\n    date_trunc('week', now() - interval '26 weeks'),\n    date_trunc('week', now()) - interval '1 week',\n    interval '1 week'\n  ) AS week\n),\nlatest AS (\n  SELECT DISTINCT ON (w.week, e.properties->>'subscription_id')\n    w.week,\n    (e.properties->>'mrr')::numeric AS mrr,\n    e.properties->>'status' AS status\n  FROM weeks w\n  JOIN events e\n    ON e.event_name = 'subscription_updated'\n   AND e.occurred_at < w.week + interval '1 week'\n  ORDER BY w.week, e.properties->>'subscription_id', e.occurred_at DESC\n)\nSELECT week::date AS week, sum(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;","bigquery":"-- MRR at the end of each week from a subscription change log.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(\n    DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 26 WEEK), ISOWEEK),\n    DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK),\n    INTERVAL 1 WEEK\n  )) AS week\n),\nlatest AS (\n  SELECT\n    w.week,\n    JSON_VALUE(e.properties, '$.subscription_id') AS subscription_id,\n    CAST(JSON_VALUE(e.properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(e.properties, '$.status') AS status\n  FROM weeks AS w\n  JOIN events AS e\n    ON e.event_name = 'subscription_updated'\n   AND DATE(e.occurred_at) < DATE_ADD(w.week, INTERVAL 1 WEEK)\n  QUALIFY ROW_NUMBER() OVER (\n    PARTITION BY w.week, JSON_VALUE(e.properties, '$.subscription_id')\n    ORDER BY e.occurred_at DESC\n  ) = 1\n)\nSELECT week, SUM(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;","snowflake":"-- MRR at the end of each week from a subscription change log. Assumes WEEK_START = 1 (Monday).\nWITH weeks AS (\n  SELECT DATEADD(week, -SEQ4(), DATE_TRUNC('week', DATEADD(week, -1, CURRENT_DATE()))) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nlatest AS (\n  SELECT\n    w.week,\n    e.properties:subscription_id::string AS subscription_id,\n    e.properties:mrr::float AS mrr,\n    e.properties:status::string AS status\n  FROM weeks AS w\n  JOIN events AS e\n    ON e.event_name = 'subscription_updated'\n   AND e.occurred_at < DATEADD(week, 1, w.week)\n  QUALIFY ROW_NUMBER() OVER (\n    PARTITION BY w.week, e.properties:subscription_id::string\n    ORDER BY e.occurred_at DESC\n  ) = 1\n)\nSELECT week, SUM(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;"},"noise":{"type":"process","min_denominator":20,"volume_unit":"active subscriptions","typical":180000},"example":{"business":"saas","level":240000,"volume":1900,"trend":0.35},"drivers":[{"id":"new-mrr","label":"New MRR","metric":"new-mrr","dropped":{"check":"Did fewer new customers start paying, or start on smaller plans?","yes":"New MRR falls below its usual range while churn holds."},"spiked":{"check":"Did a launch, a sales push or one large deal add new MRR?","yes":"New MRR jumps; check whether one customer accounts for most of it."}},{"id":"expansion","label":"Expansion","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow?","yes":"Expansion MRR falls while new and churned MRR hold."},"spiked":{"check":"Did a price change or a usage limit push customers to upgrade?","yes":"Expansion MRR jumps in the week the change shipped."}},{"id":"churn","label":"Churned and contracted MRR","metric":"churned-mrr","feed":"stripe","dropped":{"check":"Did cancellations, downgrades or failed renewals rise?","yes":"Churned MRR rises; failed payments or one large account explain most of it."},"spiked":{"check":"Did churn fall unusually low, or did failed payments recover?","yes":"Churned MRR falls and recovered dunning payments appear."}},{"id":"billing-calendar","label":"Billing calendar","dropped":{"check":"Did a cohort of annual plans come up for renewal this week?","yes":"A cluster of renewals dated one year after a big signup month."},"spiked":{"check":"Is a migration or a currency revaluation changing amounts without customers acting?","yes":"Many subscriptions change amount on the same day with no plan change."}}],"diagnose_order":["billing-calendar","churn","new-mrr","expansion"],"related":["new-mrr","expansion-mrr","churned-mrr","net-new-mrr","arpa"],"prose":{"why_it_matters":"MRR is the stock that every other subscription number flows into: new and expansion MRR add to it, churn and contraction take from it. Because it is a stock, it barely moves week to week, which is exactly why a small move matters. Read its flows to see why it moved; read MRR itself to see whether the business is growing.","pitfalls":["Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.","Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.","Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.","A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "net-revenue": { yaml: "id: net-revenue\nname: Net revenue\naliases:\n  - Weekly revenue\n  - Net sales\nfamily: revenue\ncatalog_id: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue after discounts and refunds, before tax and shipping, for orders paid this week.\n  formula: Sum of order totals − refunds issued, excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n\nnumerator:\n  label: Net revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 400000\n\nexample:\n  business: store\n  level: 1300000\n  volume: 13000\n  trend: 0.2\n\ndrivers:\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth?\n      yes: Orders fall by about as much as revenue while order value holds.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as revenue while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did the average order shrink, from a discount, a mix shift or fewer items per order?\n      yes: Order value falls while the number of orders holds.\n    spiked:\n      check: Did a few large orders or a price rise lift the average?\n      yes: Order value jumps, often driven by a handful of orders far above the usual size.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors?\n      yes: Sessions rise in one channel, and conversion holds.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which step?\n      yes: Conversion falls while traffic holds; one funnel step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which step?\n      yes: Conversion rises while traffic holds; one funnel step explains most of it.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?\n      yes: Gross sales hold while refunds rise.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refunds return to their usual share and net revenue recovers.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is last week's comparison a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this week a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n\ndiagnose_order: [calendar, orders, order-value, traffic, conversion, refunds]\n\nrelated: [orders, aov, conversion-rate, gross-sales, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Revenue is the number everyone reads first, which is why it is the worst number to act on\n    alone. It is orders times order value, and orders are traffic times conversion; a move in\n    revenue is only useful once you know which of those moved. Most weeks, nothing did, and the\n    honest answer is that the change is the ordinary wobble of a few thousand orders.\n  pitfalls:\n    - Booking revenue when the order is placed but refunds when they are issued mixes two weeks. Report both by the week they happen and say so.\n    - Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.\n    - A few very large orders can move a small store's week by 10% or more. Check the order count before the total.\n    - Revenue in several currencies needs one fixed exchange rate per week, or currency moves look like sales.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"net-revenue","name":"Net revenue","aliases":["Weekly revenue","Net sales"],"family":"revenue","catalog_id":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue after discounts and refunds, before tax and shipping, for orders paid this week.","formula":"Sum of order totals − refunds issued, excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]}],"numerator":{"label":"Net revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":400000},"example":{"business":"store","level":1300000,"volume":13000,"trend":0.2},"drivers":[{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth?","yes":"Orders fall by about as much as revenue while order value holds."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as revenue while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did the average order shrink, from a discount, a mix shift or fewer items per order?","yes":"Order value falls while the number of orders holds."},"spiked":{"check":"Did a few large orders or a price rise lift the average?","yes":"Order value jumps, often driven by a handful of orders far above the usual size."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors?","yes":"Sessions rise in one channel, and conversion holds."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which step?","yes":"Conversion falls while traffic holds; one funnel step explains most of it."},"spiked":{"check":"Did more visits buy, and at which step?","yes":"Conversion rises while traffic holds; one funnel step explains most of it."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?","yes":"Gross sales hold while refunds rise."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refunds return to their usual share and net revenue recovers."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is last week's comparison a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this week a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}}],"diagnose_order":["calendar","orders","order-value","traffic","conversion","refunds"],"related":["orders","aov","conversion-rate","gross-sales","refund-rate"],"prose":{"why_it_matters":"Revenue is the number everyone reads first, which is why it is the worst number to act on alone. It is orders times order value, and orders are traffic times conversion; a move in revenue is only useful once you know which of those moved. Most weeks, nothing did, and the honest answer is that the change is the ordinary wobble of a few thousand orders.","pitfalls":["Booking revenue when the order is placed but refunds when they are issued mixes two weeks. Report both by the week they happen and say so.","Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.","A few very large orders can move a small store's week by 10% or more. Check the order count before the total.","Revenue in several currencies needs one fixed exchange rate per week, or currency moves look like sales."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
}
